/* =================================================================================================
FILE:         sdi_sp_dashboardPulseByod_silver_adobeByodEntryPages_weekly.sql
LAYER:        Silver View
DATASET:      prj-dbi-prd-1.ds_dbi_digitalmedia_automation
VIEW NAME:    vw_sdi_pulseByod_silver_adobeByodEntryPages_weekly

SOURCE:
  prdrzranalytics.lab42.sdi_tbl_adobeFunnel_silver_byodFlowEntryPagesByChannelGroupsPlusAll_weekly

DESTINATION:
  prdrzranalytics.lab42.sdi_tbl_dashboardPulseByod_silver_adobeByodEntryPages_weekly

PURPOSE:
  Silver view for Adobe Analytics BYOD funnel entry page metrics.
  Outputs a WIDE table — one row per week_sun_to_sat.
  Pivots ChannelGroup rows into columns so each channel
  becomes its own set of prefixed metric columns.
  Applies WoW/LY comparisons and max_data_date.

  Entry page metrics track where BYOD visitors entered the site:
    byodUpvVisitors                 — total unique non-bounced BYOD visitors
    byodEntryByodPageVisitors        — entered on BYOD page
    byodEntryHomePageVisitors        — entered on homepage
    byodEntryDevicePageVisitors      — entered on device page
    byodEntryPlansPageVisitors       — entered on plans page
    byodEntryOtherPageVisitors       — entered on other page (NEW: otherpage2 only — true residual)
    byodEntryGetStartedLandingPageVisitors       — entered on Get Started Landing page (NEW)
    byodEntryByodLandingPageVisitors — entered on BYOD landing page (NEW)
    byodEntryOffersSwitchVisitors    — entered on offers/switch page (NEW)

  -- OLD OTHER reference (not a live column):
  -- Old Other = byodEntryGetStartedLandingPageVisitors + byodEntryByodLandingPageVisitors
  --           + byodEntryOffersSwitchVisitors + byodEntryOtherPageVisitors (otherpage2)
  -- Previously sourced from: sdi_raw_adobe_byod_flow_{channel}_byod_entry_otherpage_visitors_weekly_tmo

BUSINESS GRAIN:
  One row per week_sun_to_sat

SOURCE GRAIN:
  One row per WeekSunSat + ChannelGroup
  ChannelGroup values: ALL, PAID SEARCH, ORGANIC SEARCH,
                       DIRECT, SOCIAL, PROGRAMMATIC, OTHER

COLUMN NAMING CONVENTION:
  adobe_{metric}_{channel}
  Channel suffixes: allChannels, paidSearch, organicSearch, direct, social, programmatic, other

BUSINESS LOGIC:
  - No derived/ratio metrics — all metrics are raw visitor counts
  - WoW: self-join on week_sun_to_sat - 7 days (gap-safe)
  - LY:  self-join on custom_week_num - 52 (gap-safe, Sun-to-Sat anchor)
  - wow_pct / yoy_pct as decimals — NULL when prior NULL or 0
  - max_data_date: latest week_sun_to_sat with any non-null metric

CUSTOM WEEK NUMBER:
  custom_week_num = DATEDIFF(WEEK, DATE '2023-01-01', DATE_SUB(week_sun_to_sat, 6))
  LY match: current.custom_week_num - prior.custom_week_num = 52

DOWNSTREAM:
  Gold Wide : vw_sdi_pulseByod_gold_unified_wide
  Gold Long : vw_sdi_pulseByod_gold_unified_long

CHANGES:
  2026-06-XX — Other segregation:
               byodEntryOtherPageVisitors redefined to otherpage2 only (from upstream Bronze)
               Added byodEntryGetStartedLandingPageVisitors, byodEntryByodLandingPageVisitors,
               byodEntryOffersSwitchVisitors across all 7 channels with full WoW/LY/pct treatment
================================================================================================= */

CREATE OR REPLACE PROCEDURE
prdrzranalytics.lab42.sdi_sp_dashboardPulseByod_silver_adobeByodEntryPages_weekly()
LANGUAGE SQL
SQL SECURITY INVOKER
MODIFIES SQL DATA
AS
BEGIN

  CREATE OR REPLACE TABLE
  prdrzranalytics.lab42.sdi_tbl_dashboardPulseByod_silver_adobeByodEntryPages_weekly
  USING DELTA
  AS

WITH base AS (
  SELECT
    WeekSunSat                         AS week_sun_to_sat,
    ChannelGroup,
    ByodUpvVisitors,
    ByodEntryByodPageVisitors,
    ByodEntryHomePageVisitors,
    ByodEntryDevicePageVisitors,
    ByodEntryPlansPageVisitors,
    ByodEntryOtherPageVisitors,
    ByodEntryStorePageVisitors as ByodEntryGetStartedLandingPageVisitors,          -- NEW
    ByodEntryByodLandingPageVisitors,    -- NEW
    ByodEntryOffersSwitchVisitors        -- NEW
  FROM prdrzranalytics.lab42.sdi_tbl_adobeFunnel_silver_byodFlowEntryPagesByChannelGroupsPlusAll_weekly
),

pivoted AS (
  SELECT
    week_sun_to_sat,
    -- ALL CHANNELS
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_allChannels,
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_allChannels,
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_allChannels,
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_allChannels,
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_allChannels,
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_allChannels,
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_allChannels,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_allChannels,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'All Channels' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_allChannels,  -- NEW
    -- PAID SEARCH
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_paidSearch,
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_paidSearch,
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_paidSearch,
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_paidSearch,
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_paidSearch,
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_paidSearch,
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_paidSearch,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_paidSearch,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Paid Search' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_paidSearch,  -- NEW
    -- ORGANIC SEARCH
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_organicSearch,
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_organicSearch,
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_organicSearch,
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_organicSearch,
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_organicSearch,
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_organicSearch,
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_organicSearch,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_organicSearch,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Organic Search' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_organicSearch,  -- NEW
    -- DIRECT
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_direct,
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_direct,
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_direct,
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_direct,
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_direct,
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_direct,
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_direct,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_direct,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Direct' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_direct,  -- NEW
    -- SOCIAL
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_social,
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_social,
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_social,
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_social,
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_social,
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_social,
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_social,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_social,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Paid Social' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_social,  -- NEW
    -- PROGRAMMATIC
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_programmatic,
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_programmatic,
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_programmatic,
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_programmatic,
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_programmatic,
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_programmatic,
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_programmatic,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_programmatic,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Programmatic' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_programmatic,  -- NEW
    -- OTHER
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodUpvVisitors END) AS adobe_byodUpvVisitors_other,
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryByodPageVisitors END) AS adobe_byodEntryByodPageVisitors_other,
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryHomePageVisitors END) AS adobe_byodEntryHomePageVisitors_other,
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryDevicePageVisitors END) AS adobe_byodEntryDevicePageVisitors_other,
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryPlansPageVisitors END) AS adobe_byodEntryPlansPageVisitors_other,
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryOtherPageVisitors END) AS adobe_byodEntryOtherPageVisitors_other,
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryGetStartedLandingPageVisitors END) AS adobe_byodEntryGetStartedLandingPageVisitors_other,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryByodLandingPageVisitors END) AS adobe_byodEntryByodLandingPageVisitors_other,  -- NEW
    MAX(CASE WHEN ChannelGroup = 'Other' THEN ByodEntryOffersSwitchVisitors END) AS adobe_byodEntryOffersSwitchVisitors_other  -- NEW
  FROM base
  GROUP BY week_sun_to_sat
),

with_week_num AS (
  SELECT
    *,
    DATEDIFF(WEEK, DATE '2023-01-01', DATE_SUB(week_sun_to_sat, 6)) AS custom_week_num
  FROM pivoted
),

with_comparisons AS (
  SELECT
    c.week_sun_to_sat, c.custom_week_num,
    -- ALL CHANNELS
    c.adobe_byodUpvVisitors_allChannels, w.adobe_byodUpvVisitors_allChannels AS adobe_byodUpvVisitors_allChannels_wow, l.adobe_byodUpvVisitors_allChannels AS adobe_byodUpvVisitors_allChannels_ly,
    c.adobe_byodEntryByodPageVisitors_allChannels, w.adobe_byodEntryByodPageVisitors_allChannels AS adobe_byodEntryByodPageVisitors_allChannels_wow, l.adobe_byodEntryByodPageVisitors_allChannels AS adobe_byodEntryByodPageVisitors_allChannels_ly,
    c.adobe_byodEntryHomePageVisitors_allChannels, w.adobe_byodEntryHomePageVisitors_allChannels AS adobe_byodEntryHomePageVisitors_allChannels_wow, l.adobe_byodEntryHomePageVisitors_allChannels AS adobe_byodEntryHomePageVisitors_allChannels_ly,
    c.adobe_byodEntryDevicePageVisitors_allChannels, w.adobe_byodEntryDevicePageVisitors_allChannels AS adobe_byodEntryDevicePageVisitors_allChannels_wow, l.adobe_byodEntryDevicePageVisitors_allChannels AS adobe_byodEntryDevicePageVisitors_allChannels_ly,
    c.adobe_byodEntryPlansPageVisitors_allChannels, w.adobe_byodEntryPlansPageVisitors_allChannels AS adobe_byodEntryPlansPageVisitors_allChannels_wow, l.adobe_byodEntryPlansPageVisitors_allChannels AS adobe_byodEntryPlansPageVisitors_allChannels_ly,
    c.adobe_byodEntryOtherPageVisitors_allChannels, w.adobe_byodEntryOtherPageVisitors_allChannels AS adobe_byodEntryOtherPageVisitors_allChannels_wow, l.adobe_byodEntryOtherPageVisitors_allChannels AS adobe_byodEntryOtherPageVisitors_allChannels_ly,
    c.adobe_byodEntryGetStartedLandingPageVisitors_allChannels, w.adobe_byodEntryGetStartedLandingPageVisitors_allChannels AS adobe_byodEntryGetStartedLandingPageVisitors_allChannels_wow, l.adobe_byodEntryGetStartedLandingPageVisitors_allChannels AS adobe_byodEntryGetStartedLandingPageVisitors_allChannels_ly,
    c.adobe_byodEntryByodLandingPageVisitors_allChannels, w.adobe_byodEntryByodLandingPageVisitors_allChannels AS adobe_byodEntryByodLandingPageVisitors_allChannels_wow, l.adobe_byodEntryByodLandingPageVisitors_allChannels AS adobe_byodEntryByodLandingPageVisitors_allChannels_ly,
    c.adobe_byodEntryOffersSwitchVisitors_allChannels, w.adobe_byodEntryOffersSwitchVisitors_allChannels AS adobe_byodEntryOffersSwitchVisitors_allChannels_wow, l.adobe_byodEntryOffersSwitchVisitors_allChannels AS adobe_byodEntryOffersSwitchVisitors_allChannels_ly,
    -- PAID SEARCH
    c.adobe_byodUpvVisitors_paidSearch, w.adobe_byodUpvVisitors_paidSearch AS adobe_byodUpvVisitors_paidSearch_wow, l.adobe_byodUpvVisitors_paidSearch AS adobe_byodUpvVisitors_paidSearch_ly,
    c.adobe_byodEntryByodPageVisitors_paidSearch, w.adobe_byodEntryByodPageVisitors_paidSearch AS adobe_byodEntryByodPageVisitors_paidSearch_wow, l.adobe_byodEntryByodPageVisitors_paidSearch AS adobe_byodEntryByodPageVisitors_paidSearch_ly,
    c.adobe_byodEntryHomePageVisitors_paidSearch, w.adobe_byodEntryHomePageVisitors_paidSearch AS adobe_byodEntryHomePageVisitors_paidSearch_wow, l.adobe_byodEntryHomePageVisitors_paidSearch AS adobe_byodEntryHomePageVisitors_paidSearch_ly,
    c.adobe_byodEntryDevicePageVisitors_paidSearch, w.adobe_byodEntryDevicePageVisitors_paidSearch AS adobe_byodEntryDevicePageVisitors_paidSearch_wow, l.adobe_byodEntryDevicePageVisitors_paidSearch AS adobe_byodEntryDevicePageVisitors_paidSearch_ly,
    c.adobe_byodEntryPlansPageVisitors_paidSearch, w.adobe_byodEntryPlansPageVisitors_paidSearch AS adobe_byodEntryPlansPageVisitors_paidSearch_wow, l.adobe_byodEntryPlansPageVisitors_paidSearch AS adobe_byodEntryPlansPageVisitors_paidSearch_ly,
    c.adobe_byodEntryOtherPageVisitors_paidSearch, w.adobe_byodEntryOtherPageVisitors_paidSearch AS adobe_byodEntryOtherPageVisitors_paidSearch_wow, l.adobe_byodEntryOtherPageVisitors_paidSearch AS adobe_byodEntryOtherPageVisitors_paidSearch_ly,
    c.adobe_byodEntryGetStartedLandingPageVisitors_paidSearch, w.adobe_byodEntryGetStartedLandingPageVisitors_paidSearch AS adobe_byodEntryGetStartedLandingPageVisitors_paidSearch_wow, l.adobe_byodEntryGetStartedLandingPageVisitors_paidSearch AS adobe_byodEntryGetStartedLandingPageVisitors_paidSearch_ly,
    c.adobe_byodEntryByodLandingPageVisitors_paidSearch, w.adobe_byodEntryByodLandingPageVisitors_paidSearch AS adobe_byodEntryByodLandingPageVisitors_paidSearch_wow, l.adobe_byodEntryByodLandingPageVisitors_paidSearch AS adobe_byodEntryByodLandingPageVisitors_paidSearch_ly,
    c.adobe_byodEntryOffersSwitchVisitors_paidSearch, w.adobe_byodEntryOffersSwitchVisitors_paidSearch AS adobe_byodEntryOffersSwitchVisitors_paidSearch_wow, l.adobe_byodEntryOffersSwitchVisitors_paidSearch AS adobe_byodEntryOffersSwitchVisitors_paidSearch_ly,
    -- ORGANIC SEARCH
    c.adobe_byodUpvVisitors_organicSearch, w.adobe_byodUpvVisitors_organicSearch AS adobe_byodUpvVisitors_organicSearch_wow, l.adobe_byodUpvVisitors_organicSearch AS adobe_byodUpvVisitors_organicSearch_ly,
    c.adobe_byodEntryByodPageVisitors_organicSearch, w.adobe_byodEntryByodPageVisitors_organicSearch AS adobe_byodEntryByodPageVisitors_organicSearch_wow, l.adobe_byodEntryByodPageVisitors_organicSearch AS adobe_byodEntryByodPageVisitors_organicSearch_ly,
    c.adobe_byodEntryHomePageVisitors_organicSearch, w.adobe_byodEntryHomePageVisitors_organicSearch AS adobe_byodEntryHomePageVisitors_organicSearch_wow, l.adobe_byodEntryHomePageVisitors_organicSearch AS adobe_byodEntryHomePageVisitors_organicSearch_ly,
    c.adobe_byodEntryDevicePageVisitors_organicSearch, w.adobe_byodEntryDevicePageVisitors_organicSearch AS adobe_byodEntryDevicePageVisitors_organicSearch_wow, l.adobe_byodEntryDevicePageVisitors_organicSearch AS adobe_byodEntryDevicePageVisitors_organicSearch_ly,
    c.adobe_byodEntryPlansPageVisitors_organicSearch, w.adobe_byodEntryPlansPageVisitors_organicSearch AS adobe_byodEntryPlansPageVisitors_organicSearch_wow, l.adobe_byodEntryPlansPageVisitors_organicSearch AS adobe_byodEntryPlansPageVisitors_organicSearch_ly,
    c.adobe_byodEntryOtherPageVisitors_organicSearch, w.adobe_byodEntryOtherPageVisitors_organicSearch AS adobe_byodEntryOtherPageVisitors_organicSearch_wow, l.adobe_byodEntryOtherPageVisitors_organicSearch AS adobe_byodEntryOtherPageVisitors_organicSearch_ly,
    c.adobe_byodEntryGetStartedLandingPageVisitors_organicSearch, w.adobe_byodEntryGetStartedLandingPageVisitors_organicSearch AS adobe_byodEntryGetStartedLandingPageVisitors_organicSearch_wow, l.adobe_byodEntryGetStartedLandingPageVisitors_organicSearch AS adobe_byodEntryGetStartedLandingPageVisitors_organicSearch_ly,
    c.adobe_byodEntryByodLandingPageVisitors_organicSearch, w.adobe_byodEntryByodLandingPageVisitors_organicSearch AS adobe_byodEntryByodLandingPageVisitors_organicSearch_wow, l.adobe_byodEntryByodLandingPageVisitors_organicSearch AS adobe_byodEntryByodLandingPageVisitors_organicSearch_ly,
    c.adobe_byodEntryOffersSwitchVisitors_organicSearch, w.adobe_byodEntryOffersSwitchVisitors_organicSearch AS adobe_byodEntryOffersSwitchVisitors_organicSearch_wow, l.adobe_byodEntryOffersSwitchVisitors_organicSearch AS adobe_byodEntryOffersSwitchVisitors_organicSearch_ly,
    -- DIRECT
    c.adobe_byodUpvVisitors_direct, w.adobe_byodUpvVisitors_direct AS adobe_byodUpvVisitors_direct_wow, l.adobe_byodUpvVisitors_direct AS adobe_byodUpvVisitors_direct_ly,
    c.adobe_byodEntryByodPageVisitors_direct, w.adobe_byodEntryByodPageVisitors_direct AS adobe_byodEntryByodPageVisitors_direct_wow, l.adobe_byodEntryByodPageVisitors_direct AS adobe_byodEntryByodPageVisitors_direct_ly,
    c.adobe_byodEntryHomePageVisitors_direct, w.adobe_byodEntryHomePageVisitors_direct AS adobe_byodEntryHomePageVisitors_direct_wow, l.adobe_byodEntryHomePageVisitors_direct AS adobe_byodEntryHomePageVisitors_direct_ly,
    c.adobe_byodEntryDevicePageVisitors_direct, w.adobe_byodEntryDevicePageVisitors_direct AS adobe_byodEntryDevicePageVisitors_direct_wow, l.adobe_byodEntryDevicePageVisitors_direct AS adobe_byodEntryDevicePageVisitors_direct_ly,
    c.adobe_byodEntryPlansPageVisitors_direct, w.adobe_byodEntryPlansPageVisitors_direct AS adobe_byodEntryPlansPageVisitors_direct_wow, l.adobe_byodEntryPlansPageVisitors_direct AS adobe_byodEntryPlansPageVisitors_direct_ly,
    c.adobe_byodEntryOtherPageVisitors_direct, w.adobe_byodEntryOtherPageVisitors_direct AS adobe_byodEntryOtherPageVisitors_direct_wow, l.adobe_byodEntryOtherPageVisitors_direct AS adobe_byodEntryOtherPageVisitors_direct_ly,
    c.adobe_byodEntryGetStartedLandingPageVisitors_direct, w.adobe_byodEntryGetStartedLandingPageVisitors_direct AS adobe_byodEntryGetStartedLandingPageVisitors_direct_wow, l.adobe_byodEntryGetStartedLandingPageVisitors_direct AS adobe_byodEntryGetStartedLandingPageVisitors_direct_ly,
    c.adobe_byodEntryByodLandingPageVisitors_direct, w.adobe_byodEntryByodLandingPageVisitors_direct AS adobe_byodEntryByodLandingPageVisitors_direct_wow, l.adobe_byodEntryByodLandingPageVisitors_direct AS adobe_byodEntryByodLandingPageVisitors_direct_ly,
    c.adobe_byodEntryOffersSwitchVisitors_direct, w.adobe_byodEntryOffersSwitchVisitors_direct AS adobe_byodEntryOffersSwitchVisitors_direct_wow, l.adobe_byodEntryOffersSwitchVisitors_direct AS adobe_byodEntryOffersSwitchVisitors_direct_ly,
    -- SOCIAL
    c.adobe_byodUpvVisitors_social, w.adobe_byodUpvVisitors_social AS adobe_byodUpvVisitors_social_wow, l.adobe_byodUpvVisitors_social AS adobe_byodUpvVisitors_social_ly,
    c.adobe_byodEntryByodPageVisitors_social, w.adobe_byodEntryByodPageVisitors_social AS adobe_byodEntryByodPageVisitors_social_wow, l.adobe_byodEntryByodPageVisitors_social AS adobe_byodEntryByodPageVisitors_social_ly,
    c.adobe_byodEntryHomePageVisitors_social, w.adobe_byodEntryHomePageVisitors_social AS adobe_byodEntryHomePageVisitors_social_wow, l.adobe_byodEntryHomePageVisitors_social AS adobe_byodEntryHomePageVisitors_social_ly,
    c.adobe_byodEntryDevicePageVisitors_social, w.adobe_byodEntryDevicePageVisitors_social AS adobe_byodEntryDevicePageVisitors_social_wow, l.adobe_byodEntryDevicePageVisitors_social AS adobe_byodEntryDevicePageVisitors_social_ly,
    c.adobe_byodEntryPlansPageVisitors_social, w.adobe_byodEntryPlansPageVisitors_social AS adobe_byodEntryPlansPageVisitors_social_wow, l.adobe_byodEntryPlansPageVisitors_social AS adobe_byodEntryPlansPageVisitors_social_ly,
    c.adobe_byodEntryOtherPageVisitors_social, w.adobe_byodEntryOtherPageVisitors_social AS adobe_byodEntryOtherPageVisitors_social_wow, l.adobe_byodEntryOtherPageVisitors_social AS adobe_byodEntryOtherPageVisitors_social_ly,
    c.adobe_byodEntryGetStartedLandingPageVisitors_social, w.adobe_byodEntryGetStartedLandingPageVisitors_social AS adobe_byodEntryGetStartedLandingPageVisitors_social_wow, l.adobe_byodEntryGetStartedLandingPageVisitors_social AS adobe_byodEntryGetStartedLandingPageVisitors_social_ly,
    c.adobe_byodEntryByodLandingPageVisitors_social, w.adobe_byodEntryByodLandingPageVisitors_social AS adobe_byodEntryByodLandingPageVisitors_social_wow, l.adobe_byodEntryByodLandingPageVisitors_social AS adobe_byodEntryByodLandingPageVisitors_social_ly,
